SELECT (
        SELECT emp42_grade
          FROM emp42_eval_grade
         WHERE emp42_eval_grade_id = f_get_empEvalGradeId(#{evalListStdId}, SUM(emp44_eval_grade_score)::numeric)
       )
  FROM emp44_eval_write
 WHERE emp44_evaluator_id = #{personId}
   AND emp44_eval_target_id = #{evalTargetId}

SELECT COUNT(*)
  FROM emp44_eval_write
 WHERE emp44_evaluator_id = #{personId}
   AND emp44_eval_target_id = #{evalTargetId}
   AND emp44_eval_list_id = #{evalListId}

SELECT COUNT(*)
  FROM emp43_eval_target
 WHERE emp43_eval_target_id = #{evalTargetId}
   AND emp43_company_id = #{companyId}

mapper.update:
UPDATE emp44_eval_write
   SET emp44_eval_grade_id = #{evalGradeId}
     , emp44_eval_grade_score = TRUNC((
                                    SELECT CASE WHEN #{orgHeadYn} = 'true'
                                                THEN emp41_weight_leader
                                                ELSE emp41_weight_member
                                                END
                                      FROM emp41_eval_list
                                     WHERE emp44_eval_list_id = emp41_eval_list_id
                                )*(
                                    SELECT emp42_grade_weight
                                      FROM emp42_eval_grade
                                     WHERE emp42_eval_grade_id = #{evalGradeId}
                                ), 1)
 WHERE emp44_evaluator_id = #{personId}
   AND emp44_eval_target_id = #{evalTargetId}
   AND emp44_eval_list_id = #{evalListId}
